struct ServiceProxy<S> { inner: S, metrics: Arc<Metrics> }
impl<S> ServiceApi for ServiceProxy<S>
where
    S: ServiceApi,
{
    fn call(&self, request: Request) -> Response {
        let started = Instant::now();
        let response = self.inner.call(request);          // delegate unchanged
        self.metrics.observe("call", started.elapsed());
        response                                          // same contract
    }
}
